const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers || {};
const lowerHeaders = Object.fromEntries(
  Object.entries(headers).map(([k, v]) => [k.toLowerCase(), String(v ?? '')])
);

const secret = $env.YTTOTEXT_WEBHOOK_SECRET || 'whsec_REPLACE_WITH_YOUR_SECRET';
const timestamp = lowerHeaders['x-yttotext-timestamp'] || '';
const signature = lowerHeaders['x-yttotext-signature'] || '';
const eventId = lowerHeaders['x-yttotext-event-id'] || '';

const rawBody = typeof item.json.rawBody === 'string'
  ? item.json.rawBody
  : JSON.stringify(item.json.body ?? item.json);

const ageSeconds = Math.abs(Date.now() / 1000 - Number(timestamp));
const freshTimestamp = /^\d+$/.test(timestamp) && ageSeconds <= 300;

const expected = 'v1=' + crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

const expectedBuf = Buffer.from(expected, 'utf8');
const receivedBuf = Buffer.from(signature, 'utf8');
const validSignature = freshTimestamp
  && expectedBuf.length === receivedBuf.length
  && crypto.timingSafeEqual(expectedBuf, receivedBuf);

const payload = item.json.body && typeof item.json.body === 'object'
  ? item.json.body
  : JSON.parse(rawBody || '{}');

return [{ json: { validSignature, eventId, timestamp, payload } }];

const { eventId, payload } = $input.first().json;
const video = payload.video || payload;
const transcriptObj = payload.transcript || {};

const videoId = video.videoId || video.id || '';
const videoTitle = video.title || transcriptObj.title || 'Untitled YouTube Video';
const channelTitle = payload.channel?.title || payload.watchlistName || 'Monitored Channel';
const videoUrl = video.url || (videoId ? `https://www.youtube.com/watch?v=${videoId}` : '');
const rawText = (transcriptObj.text || payload.text || '').replace(/\s+/g, ' ').trim();

const wordCount = rawText ? rawText.split(' ').length : 0;
const readMinutes = Math.max(1, Math.round(wordCount / 220));
const maxChars = 24000;
const truncated = rawText.length > maxChars;
const transcriptForLlm = truncated ? rawText.slice(0, maxChars) + '\n[Truncated for summary context]' : rawText;

return [{
  json: {
    eventId,
    receivedAt: new Date().toISOString(),
    channelTitle,
    videoId,
    videoTitle,
    videoUrl,
    language: transcriptObj.language || payload.language || 'en',
    wordCount,
    readMinutes,
    truncated,
    transcriptForLlm
  }
}];

const meta = $('Clean & Cap Transcript').first().json;
const aiItem = $input.first().json;
const content = aiItem.message?.content ?? aiItem.text ?? aiItem;
let brief = {};
try {
  brief = typeof content === 'string' ? JSON.parse(content) : content;
} catch {
  brief = { oneLineSummary: String(content || ''), keyTakeaways: [], notableQuotes: [], actionItems: [] };
}

const takeaways = Array.isArray(brief.keyTakeaways) ? brief.keyTakeaways : [];
const quotes = Array.isArray(brief.notableQuotes) ? brief.notableQuotes : [];
const actions = Array.isArray(brief.actionItems) ? brief.actionItems : [];

const slackMessage = [
  `*New Video Brief — ${meta.channelTitle}*`,
  `<${meta.videoUrl}|${meta.videoTitle}> (${meta.wordCount} words · ~${meta.readMinutes} min read)`,
  '',
  `*Summary:* ${brief.oneLineSummary || 'N/A'}`,
  takeaways.length ? '\n*Key takeaways:*\n' + takeaways.map(t => `• ${t}`).join('\n') : '',
  quotes.length ? '\n*Notable quote:*\n> ' + quotes[0] : '',
  actions.length ? '\n*Suggested next step:*\n' + actions.map(a => `- ${a}`).join('\n') : ''
].filter(Boolean).join('\n');

return [{
  json: {
    ...meta,
    oneLineSummary: brief.oneLineSummary || '',
    keyTakeawaysText: takeaways.join(' | '),
    actionItemsText: actions.join(' | '),
    slackMessage
  }
}];
